# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels, round_spans


class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        got = round_labels([Span(540, 1035)], 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest(self):
        got = round_spans([Span(543, 1028)], 15)
        self.assertEqual(got, [Span(540, 1035)])

    def test_halves_round_up(self):
        got = round_spans([Span(15, 45)], 30)
        self.assertEqual(got, [Span(30, 60)])

    def test_many_spans_keep_order(self):
        spans = [Span(60, 125), Span(0, 31)]
        got = round_labels(spans, 30)
        self.assertEqual(
            got,
            ["01:00-02:00 (1h 0m)", "00:00-00:30 (0h 30m)"],
        )

    def test_end_of_day(self):
        got = round_spans([Span(1400, 1439)], 30)
        self.assertEqual(got, [Span(1410, 1440)])

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(1, 5)], 15)


if __name__ == "__main__":
    unittest.main()
